const {chromium}=require('playwright'),http=require('http'),fs=require('fs'),path=require('path'),a=require('node:assert/strict');const root=path.resolve(__dirname,'..'),out=path.join(root,'qa/career-page-review-20261116');let browser;const server=http.createServer((req,res)=>{const file=path.resolve(root,'.'+new URL(req.url,'http://localhost').pathname.replace(/^\/$/,'/index.html'));if(!file.startsWith(root+'/'))return res.end();fs.readFile(file,(e,b)=>{res.statusCode=e?404:200;res.setHeader('Content-Type',({'.js':'application/javascript','.html':'text/html','.css':'text/css','.webp':'image/webp','.ttf':'font/ttf'})[path.extname(file)]||'application/octet-stream');res.end(e?'missing':b);});});
(async()=>{const report={scope:'Local isolated Chromium touchscreen slot947, not production or real phone',errors:[],steps:[]};try{await new Promise(r=>server.listen(0,'127.0.0.1',r));browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});const context=await browser.newContext({viewport:{width:390,height:844},hasTouch:true,isMobile:true,reducedMotion:'reduce'}),p=await context.newPage();p.on('pageerror',e=>report.errors.push(e.message));await p.goto('http://127.0.0.1:'+server.address().port,{waitUntil:'networkidle'});await p.locator('#enterGame').click();await p.evaluate(()=>{slot=947;$('job').value='barista';$('start').click();clearModals();state.housing='family';state.housingCost=500;state.housingLease={key:'family',monthly:500,depositHeld:0,startMonth:0};state.monthlyPayments={month:state.month,housing:500,living:800,premiums:0};state.homeArrival={fromMonth:-1,targetMonth:0,status:'completed'};save();openGame();clearModals();openRoom();});await p.evaluate(()=>CareerPages.skills('career'));await p.locator('.career-scene img').evaluate(i=>i.decode());await p.screenshot({path:path.join(out,'local-career-skills-390.png'),fullPage:false});a.match(await p.locator('.career-overlay').evaluate(e=>getComputedStyle(e).backgroundImage),/room-phone-20261101/);for(const [width,height] of [[320,568],[390,844],[430,932]]){await p.setViewportSize({width,height});const b=await p.locator('.career-paper').boundingBox();a.ok(b.y>=0&&b.y+b.height<=height+1);a.ok(await p.locator('.career-content').evaluate(e=>e.scrollWidth<=e.clientWidth));}console.log('Skills room background and three viewport checks passed');a.deepEqual(report.errors,[]);}finally{await browser?.close();server.close();}})();